package org.brightstats.stats;

import java.util.*;
import org.apache.commons.math3.special.Gamma;

/** Cross-group affine RAM nesting proof and regular joint-likelihood comparisons. */
public final class MultiGroupSemComparison {
    private MultiGroupSemComparison(){}
    public record Result(double restrictedChiSquare,double unrestrictedChiSquare,int restrictedDf,int unrestrictedDf,double difference,int differenceDf,double pValue,double deltaCfi,double deltaRmsea,double restrictedAic,double unrestrictedAic,double restrictedBic,double unrestrictedBic,String nestingProof){}
    public static Result compare(MultiGroupSem.Fit restricted,MultiGroupSem.Fit unrestricted){validate(restricted,unrestricted);if(!SemComparison.nested(combined(restricted),combined(unrestricted)))throw new IllegalArgumentException("Joint RAM constraints are not demonstrably nested. Different latent-mean gauges need a separately justified invariance comparison.");return difference(restricted,unrestricted,"Explicit combined-group affine RAM fixed/equality constraints");}
    static Result invarianceDifference(MultiGroupSem.Fit restricted,MultiGroupSem.Fit unrestricted,String proof){validate(restricted,unrestricted);return difference(restricted,unrestricted,proof);}
    private static Result difference(MultiGroupSem.Fit restricted,MultiGroupSem.Fit unrestricted,String proof){int df=restricted.degreesOfFreedom()-unrestricted.degreesOfFreedom();if(df<=0)throw new IllegalArgumentException("The restricted joint model must have fewer free parameters.");double difference=restricted.chiSquare()-unrestricted.chiSquare();if(difference< -1e-6*Math.max(1,restricted.chiSquare()))throw new IllegalArgumentException("The unrestricted joint likelihood is worse; resolve optimization before comparison.");difference=Math.max(0,difference);return new Result(restricted.chiSquare(),unrestricted.chiSquare(),restricted.degreesOfFreedom(),unrestricted.degreesOfFreedom(),difference,df,Gamma.regularizedGammaQ(df*.5,difference*.5),restricted.cfi()-unrestricted.cfi(),restricted.rmsea()-unrestricted.rmsea(),restricted.aic(),unrestricted.aic(),restricted.bic(),unrestricted.bic(),proof);}
    private static void validate(MultiGroupSem.Fit restricted,MultiGroupSem.Fit unrestricted){
        if(restricted.options().likelihood()!=unrestricted.options().likelihood()||restricted.options().meanStructure()!=unrestricted.options().meanStructure()||restricted.groups().size()!=unrestricted.groups().size())throw new IllegalArgumentException("Joint comparisons require the same groups, likelihood and mean structure.");for(var fit:List.of(restricted,unrestricted)){if(!fit.converged()||!fit.identified()||!fit.proper())throw new IllegalArgumentException("Joint comparisons require converged, identified, proper fits.");if(fit.parameters().stream().anyMatch(p->p.lower()!=null||p.upper()!=null))throw new IllegalArgumentException("Regular joint likelihood-ratio tests do not cover configured parameter bounds.");}for(int g=0;g<restricted.groups().size();g++){var a=restricted.groups().get(g).input();var b=unrestricted.groups().get(g).input();if(!a.name().equals(b.name())||a.observations()!=b.observations()||!a.model().variables().equals(b.model().variables())||!Arrays.equals(a.model().observed(),b.model().observed())||!same(a.covariance(),b.covariance())||restricted.options().meanStructure()&&!same(new double[][]{a.means()},new double[][]{b.means()}))throw new IllegalArgumentException("Joint comparisons require identical ordered group variables and sample moments.");}
    }
    private static boolean same(double[][] a,double[][] b){if(a.length!=b.length)return false;for(int i=0;i<a.length;i++){if(a[i].length!=b[i].length)return false;for(int j=0;j<a[i].length;j++)if(Math.abs(a[i][j]-b[i][j])>1e-10*Math.max(1,Math.abs(a[i][j])))return false;}return true;}
    private static SemModel.Model combined(MultiGroupSem.Fit fit){
        int size=fit.groups().stream().mapToInt(g->g.input().model().variables().size()).sum();if(size>2000)throw new IllegalArgumentException("Joint RAM model is too large for the current explicit affine nesting proof.");List<String> variables=new ArrayList<>();List<Integer> observed=new ArrayList<>();double[][] a=new double[size][size],s=new double[size][size];double[] m=new double[size];List<List<SemModel.Location>> locations=new ArrayList<>();for(int j=0;j<fit.parameters().size();j++)locations.add(new ArrayList<>());int offset=0;
        for(int g=0;g<fit.groups().size();g++){var group=fit.groups().get(g);var model=group.input().model();double[][] ga=model.directed(),gs=model.covariance();double[] gm=model.intercepts();int[] mapping=group.globalParameters();for(int i=0;i<model.variables().size();i++){variables.add("Group "+g+" variable "+i+": "+model.variables().get(i));m[offset+i]=gm[i];for(int j=0;j<model.variables().size();j++){a[offset+i][offset+j]=ga[i][j];s[offset+i][offset+j]=gs[i][j];}}for(int index:model.observed())observed.add(offset+index);for(int j=0;j<model.parameters().size();j++)for(var location:model.parameters().get(j).locations())locations.get(mapping[j]).add(new SemModel.Location(location.kind(),offset+location.row(),location.kind()==SemModel.Kind.INTERCEPT?0:offset+location.column()));offset+=model.variables().size();}
        List<SemModel.Parameter> parameters=new ArrayList<>();for(int j=0;j<fit.parameters().size();j++)parameters.add(new SemModel.Parameter("Global parameter "+j,locations.get(j),fit.parameters().get(j).start(),fit.parameters().get(j).scale()));return new SemModel.Model(variables,observed.stream().mapToInt(Integer::intValue).toArray(),a,s,m,parameters);
    }
}
